import {config} from './config.js';
const sessionKey='cosmos-admin-session';
let refreshing;
function session(){try{return JSON.parse(sessionStorage.getItem(sessionKey)||'null');}catch{return null;}}
function saveSession(value){if(value)sessionStorage.setItem(sessionKey,JSON.stringify(value));else sessionStorage.removeItem(sessionKey);}
async function authRequest(path,body,token){const response=await fetch(config.url+'/auth/v1/'+path,{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.msg||data.error_description||data.message||'Sign-in could not be completed.');return data;}
async function accessToken(){let value=session();if(!value)return null;if(value.expires_at*1000<Date.now()+30000){if(!refreshing)refreshing=authRequest('token?grant_type=refresh_token',{refresh_token:value.refresh_token}).then(data=>{saveSession(data);return data;}).catch(error=>{saveSession(null);throw error;}).finally(()=>{refreshing=null;});value=await refreshing;}return value.access_token;}
export async function request(path,{method='GET',body,admin=false,headers={}}={}){const token=admin?await accessToken():null;if(admin&&!token)throw new Error('Please sign in to continue.');const response=await fetch(config.url+path,{method,headers:{apikey:config.key,...(token?{Authorization:'Bearer '+token}:{}),...(body!==undefined?{'Content-Type':'application/json'}:{}),...headers},...(body!==undefined?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)});const text=await response.text();let data;try{data=text?JSON.parse(text):null;}catch{data=null;}if(!response.ok){if(response.status===401&&admin)saveSession(null);throw new Error(data?.message||data?.error||'The request could not be completed. Please try again.');}return data;}
export async function loadPublic(){const [properties,settings]=await Promise.all([request('/rest/v1/properties?select=*&status=eq.published&order=sort_order.asc,created_at.asc'),request('/rest/v1/site_settings?id=eq.1&select=*')]);return {properties,settings:settings[0]};}
export async function login(email,password){const data=await authRequest('token?grant_type=password',{email,password});saveSession(data);try{if(!await isAdmin())throw new Error('This account is not authorized for Cosmos administration.');}catch(error){await logout();throw error;}return data.user;}
export async function isAdmin(){if(!session())return false;return await request('/rest/v1/rpc/is_cosmos_admin',{method:'POST',body:{},admin:true});}
export async function logout(){const token=session()?.access_token;saveSession(null);if(token)await authRequest('logout',{},token).catch(()=>{});}
export async function uploadImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw new Error('Choose a JPG, PNG or WebP image under 5 MB.');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];const path='listings/'+crypto.randomUUID()+'.'+ext;const token=await accessToken();if(!token)throw new Error('Please sign in again.');const response=await fetch(config.url+'/storage/v1/object/property-images/'+path,{method:'POST',headers:{apikey:config.key,Authorization:'Bearer '+token,'Content-Type':file.type,'x-upsert':'false'},body:file,signal:AbortSignal.timeout(60000)});if(!response.ok)throw new Error('Image upload failed. Please check your session and try again.');return config.url+'/storage/v1/object/public/property-images/'+path;}
export async function submitEnquiry(values){const response=await fetch(config.url+'/functions/v1/enquiry',{method:'POST',headers:{apikey:config.key,Authorization:'Bearer '+config.functionKey,'Content-Type':'application/json'},body:JSON.stringify(values),signal:AbortSignal.timeout(20000)});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Your enquiry could not be saved. Please use email or WhatsApp.');return data;}
